SBP=$(cat /tmp/sbp_token); python3 - "$SBP" <<'EOF'
import json, subprocess, sys
SBP=sys.argv[1]
p=subprocess.run(['curl','-s','--max-time','20','-H',f'Authorization: Bearer {SBP}','https://api.supabase.com/v1/projects/kvclcdjmjghndxsngfzb/api-keys?reveal=true'],capture_output=True,text=True)
try:
    keys=json.loads(p.stdout)
    for k in keys:
        name=k.get('name'); api_key=k.get('api_key','')
        print(name, '->', api_key[:12]+'...', 'len', len(api_key))
        if name=='anon': open('/tmp/anon','w').write(api_key)
        if name=='service_role': open('/tmp/srk','w').write(api_key)
except Exception as e:
    print('ERR', e, p.stdout[:300])
EOF

